"""The field COMMAND window (CmdNonCmbtDat), generated by src/window_renderer.py, against the NES screenshots it
replaces: 0 differing pixels, at every scale, in white and in low HP red, with the cursor at every entry, hidden and
absent. See tests/nes_screen_diff.py.

The screenshots have no cursor in them. The reference for each cursor position is the screenshot with the NES cursor
tile (CURSOR_TILE, itself checked against the battle window screenshots in tests/test_generated_windows.py) put in the
tile CmdNonCmbtDat's bytes give, worked out here from those bytes rather than from src/windows.py.
"""
import os
import tempfile
from unittest import TestCase
from unittest.mock import patch

import pygame

from src.color import RED, WHITE
from src.config.test_config import test_config
from src.cursor import CURSOR_TILE, draw_cursor_tile
from src.directories import Directories
from src.window_renderer import render_window
from src.windows import COMMAND_LAYOUT, COMMAND_WINDOW
from tests.nes_screen_diff import compare_with_screenshot, count_differing_pixels, load_screenshot

SCALES = (1, 2, 3)
COLORS = (WHITE, RED)
DIFF_DIR = os.path.join(tempfile.gettempdir(), 'dragon_warrior_screen_diffs')

# CmdNonCmbtDat ($B054): window columns $08 (2 columns, 8 tiles apart), cursor home $21 (Y = 2 tiles, X = 1 tile).
# WndCalcSelResult numbers the entries WndCol * 4 + WndRow; WndDownPressed moves the cursor 2 tile rows.
NES_ENTRIES = ("TALK", "STATUS", "STAIRS", "SEARCH", "SPELL", "ITEM", "DOOR", "TAKE")


def nes_cursor_tile(entry: int) -> tuple[int, int]:
    column, row = divmod(entry, 4)
    return (0x21 & 0x0F) + 8 * column, (0x21 >> 4) + 2 * row


def screenshot_with_cursor(screenshot_path: str, entry: int, color: tuple, nes_pixel: int) -> pygame.Surface:
    """The screenshot (colors mapped as compare_with_screenshot maps them), with the NES cursor in the entry's tile."""
    reference = load_screenshot(screenshot_path, nes_pixel, color)
    column, row = nes_cursor_tile(entry)
    tile = 8 * nes_pixel
    draw_cursor_tile(reference, column * tile, row * tile, nes_pixel, color)
    return reference


class TestCommandWindow(TestCase):
    """CmdNonCmbtDat against data/images/command_menu_static.png and command_menu_background.png."""

    @classmethod
    def setUpClass(cls):
        pygame.init()
        directories = Directories(test_config)
        cls.static_screenshot = directories.COMMAND_MENU_STATIC_BACKGROUND_PATH  # the window, no cursor
        cls.title_only_screenshot = directories.COMMAND_MENU_BACKGROUND_PATH  # the border and title, no entries

    @classmethod
    def tearDownClass(cls):
        pygame.quit()

    def assert_same(self, generated: pygame.Surface, reference: pygame.Surface) -> None:
        self.assertEqual(0, count_differing_pixels(generated, reference))

    def assert_matches_screenshot(self, generated: pygame.Surface, screenshot: str, color, nes_pixel, name) -> None:
        result = compare_with_screenshot(generated, screenshot, nes_pixel, window_color=color, diff_dir=DIFF_DIR,
                                         name=name)
        self.assertEqual(0, result.differing_pixels, str(result))

    def test_layout_matches_the_window_data(self):
        self.assertEqual((6, 1, 8, 5), tuple(COMMAND_WINDOW))  # height $05, width $10 tiles, position $16
        self.assertEqual(tuple(nes_cursor_tile(entry) for entry in range(8)), COMMAND_LAYOUT.cursor_tiles)
        self.assertEqual(NES_ENTRIES, tuple(text.text for text in COMMAND_LAYOUT.texts))

    def test_every_cursor_position(self):
        for scale in SCALES:
            for color in COLORS:
                for entry, name in enumerate(NES_ENTRIES):
                    with self.subTest(scale=scale, color=color, entry=name):
                        generated = render_window(COMMAND_LAYOUT, color, scale, cursor_index=entry)
                        reference = screenshot_with_cursor(self.static_screenshot, entry, color, scale)
                        self.assert_same(generated, reference)

    def test_cursor_references_differ_from_the_screenshot_by_the_arrow_only(self):
        # So the cursor tests do check the cursor: the arrow's pixels, and nothing else, differ from the screenshot
        arrow_pixels = sum(line.count('#') for line in CURSOR_TILE)
        for scale in SCALES:
            for entry in range(8):
                with self.subTest(scale=scale, entry=entry):
                    reference = screenshot_with_cursor(self.static_screenshot, entry, WHITE, scale)
                    plain = load_screenshot(self.static_screenshot, scale)
                    self.assertEqual(arrow_pixels * scale * scale, count_differing_pixels(reference, plain))

    def test_cursor_hidden(self):
        # The "off" half of the blink blanks the cursor's tile: the screenshot without a cursor, wherever it is
        for scale in SCALES:
            for color in COLORS:
                for entry, name in enumerate(NES_ENTRIES):
                    with self.subTest(scale=scale, color=color, entry=name):
                        generated = render_window(COMMAND_LAYOUT, color, scale, cursor_index=entry,
                                                  cursor_visible=False)
                        self.assert_matches_screenshot(generated, self.static_screenshot, color, scale,
                                                       f'command_hidden_{entry}_{scale}_{color}')

    def test_no_cursor(self):
        for scale in SCALES:
            for color in COLORS:
                with self.subTest(scale=scale, color=color):
                    self.assert_matches_screenshot(render_window(COMMAND_LAYOUT, color, scale), self.static_screenshot,
                                                   color, scale, f'command_no_cursor_{scale}_{color}')

    def test_border_and_title(self):
        layout = COMMAND_LAYOUT._replace(texts=())
        for scale in SCALES:
            for color in COLORS:
                with self.subTest(scale=scale, color=color):
                    self.assert_matches_screenshot(render_window(layout, color, scale), self.title_only_screenshot,
                                                   color, scale, f'command_title_only_{scale}_{color}')

    def test_drawn_by_the_game(self):
        # What CommandMenu actually draws on the game screen, at the game's scale, where the window goes
        from src.game import Game
        config = dict(test_config, NO_BLIT=False, NO_WAIT=True, RENDER_TEXT=True)
        with patch('src.game.SCALED'):
            game = Game(config)
        cmd_menu = game.cmd_menu
        tile_size, scale = config['TILE_SIZE'], config['SCALE']
        area = pygame.Rect(6 * tile_size, 1 * tile_size, 8 * tile_size, 5 * tile_size)
        cmd_menu.menu.enable()
        for color in COLORS:
            game.set_window_color(color)
            for entry, name in enumerate(NES_ENTRIES):
                cmd_menu.menu.selected = entry
                with self.subTest(color=color, entry=name):
                    game.screen.fill((1, 2, 3))
                    with patch.object(cmd_menu.cursor, 'visible', return_value=True):
                        self.assertEqual(area, cmd_menu.draw_command_window())
                    reference = screenshot_with_cursor(self.static_screenshot, entry, color, scale)
                    self.assert_same(game.screen.subsurface(area), reference)
                    # The "off" half of the blink: the screenshot as it is
                    with patch.object(cmd_menu.cursor, 'visible', return_value=False):
                        cmd_menu.draw_command_window()
                    result = compare_with_screenshot(game.screen, self.static_screenshot, scale, window_color=color,
                                                     area=area, diff_dir=DIFF_DIR, name=f'command_game_{entry}')
                    self.assertEqual(0, result.differing_pixels, str(result))
